INSERT INTO "company_settings" ("id", "company_name", "tagline", "address", "phone", "gstin", "fssai_license", "invoice_prefix", "invoice_footer_notes", "print_format", "allow_negative_stock", "email", "business_hours", "google_maps_url", "instagram_url", "youtube_url", "created_at", "updated_at") VALUES ('22acad67-565b-4e8b-9635-d57313126257', 'Vahanvati Gruh Udhyog', 'હાથ વણાટના સ્પે. સારેવડા તેમજ સેવો તથા વડી બનાવનાર.', 'હાઈસ્કૂલની પાસે, નડિયાદ - પેટલાદ રોડ, પાડગોલ - ૩૮૮ ૪૪૦', '+91 97149 17851 / +91 97121 15118', '24BCIPP6428E1ZL', '20720004000511', 'VGU', 'વેચેલો માલ પાછો લેવામાં આવશે નહીં. • ન્યાય ક્ષેત્ર આણંદ રહેશે.', 'THERMAL_3INCH', FALSE, 'info@vahanvati.com', 'Monday - Sunday: 8:00 AM - 9:00 PM', 'https://www.google.com/maps/place/Vahanvati+Gruh+Udhyog+-+Handmade+Papad+in+Padgol/@22.5913772,72.8318268,17z/data=!4m16!1m9!3m8!1s0x395e5189455f6d4f:0x497aa9c788664c0b!2sVahanvati+Gruh+Udhyog+-+Handmade+Papad+in+Padgol!8m2!3d22.5913772!4d72.8318268!9m1!1b1!16s%2Fg%2F11qqwxzf4m!3m5!1s0x395e5189455f6d4f:0x497aa9c788664c0b!8m2!3d22.5913772!4d72.8318268!16s%2Fg%2F11qqwxzf4m?entry=ttu&g_ep=EgoyMDI2MDkwOS4wIKXMDSoASAFQAw%3D%3D', 'https://www.instagram.com/vahanvatigruhudhyog/', 'https://www.youtube.com/watch?v=FrB9KyMpOxQ', '2026-09-05T07:34:56.375Z'::timestamptz, '2026-09-22T05:52:24.764Z'::timestamptz) ON CONFLICT ("id") DO UPDATE SET "company_name" = EXCLUDED."company_name", "tagline" = EXCLUDED."tagline", "address" = EXCLUDED."address", "phone" = EXCLUDED."phone", "gstin" = EXCLUDED."gstin", "fssai_license" = EXCLUDED."fssai_license", "invoice_prefix" = EXCLUDED."invoice_prefix", "invoice_footer_notes" = EXCLUDED."invoice_footer_notes", "print_format" = EXCLUDED."print_format", "allow_negative_stock" = EXCLUDED."allow_negative_stock", "email" = EXCLUDED."email", "business_hours" = EXCLUDED."business_hours", "google_maps_url" = EXCLUDED."google_maps_url", "instagram_url" = EXCLUDED."instagram_url", "youtube_url" = EXCLUDED."youtube_url", "updated_at" = EXCLUDED."updated_at";
INSERT INTO "website_contents" ("id", "section", "content", "updated_at", "updated_by") VALUES ('1a3764ba-5338-4057-8bf8-8db7ba6c80eb', 'about', '{"story":{"title":"The Story of Vahanvati Gruh Udhyog","titleGu":"વહાણવટી ગૃહ ઉદ્યોગ — સ્વાદ અને પરંપરાની સફર","paragraphs":["Rooted in the heart of Padgol along the Nadiad-Petlad Road in Anand, Gujarat, Vahanvati Gruh Udhyog was established with a singular vision: to bring the authentic, nostalgic taste of homemade Gujarati Sarewada, Sevo, and Vadi to every household.","Our specialty lies in our signature \"હાથ વણાટ\" (hand-weaving) technique. Unlike industrial mass-produced snacks, our products are crafted by skilled local women and artisans who have inherited these culinary arts across generations.","We combine natural ingredients, pure drinking water, natural spices, and the abundant Gujarat sunshine for traditional curing. Certified under FSSAI license 20720004000511, our production kitchen adheres strictly to cleanliness, purity, and uncompromising food safety standards."]},"values":[{"title":"Purity & Honesty","description":"Using only the finest grains, pulses, and traditional spices with zero adulteration."},{"title":"Artisanal Preservation","description":"Keeping alive the authentic hand-spun Sarewada techniques unique to Charotar."},{"title":"Customer Trust","description":"Serving thousands of local families, NRI patrons, and festive celebrations with consistent delight."}],"qualityStandards":{"gstin":"24BCIPP6428E1ZL","location":"Padgol, Nadiad - Petlad Road, Dist. Anand - 388440, Gujarat","fssaiNumber":"20720004000511"}}'::jsonb, '2026-09-14T10:35:42.070Z'::timestamptz, NULL) ON CONFLICT ("section") DO UPDATE SET "content" = EXCLUDED."content", "updated_at" = EXCLUDED."updated_at", "updated_by" = EXCLUDED."updated_by";
INSERT INTO "website_contents" ("id", "section", "content", "updated_at", "updated_by") VALUES ('6a73bee6-d731-4c1d-b13e-94c838818b40', 'announcement', '{"text":"સ્વાગત છે વહાણવટી ગૃહ ઉદ્યોગમાં — શુદ્ધ, તાજા અને ગુણવત્તાસભર ગૃહ ઉદ્યોગ ઉત્પાદનો!"}'::jsonb, '2026-09-14T10:24:20.371Z'::timestamptz, NULL) ON CONFLICT ("section") DO UPDATE SET "content" = EXCLUDED."content", "updated_at" = EXCLUDED."updated_at", "updated_by" = EXCLUDED."updated_by";
